ALTER TABLE public.facturas_ecf_lineas ALTER COLUMN descripcion SET DEFAULT '—';
CREATE OR REPLACE FUNCTION public.validar_destino_linea_ecf() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF NEW.transporte_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.transportes WHERE id=NEW.transporte_id AND eliminado_en IS NULL) THEN RAISE EXCEPTION 'Transporte no disponible'; END IF; IF NEW.expediente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.expedientes WHERE id=NEW.expediente_id AND eliminado_en IS NULL) THEN RAISE EXCEPTION 'Expediente no disponible'; END IF; IF NEW.valor<0 OR NEW.itbis<0 THEN RAISE EXCEPTION 'Importe de renglón inválido'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validar_destino_linea_ecf BEFORE INSERT OR UPDATE ON public.facturas_ecf_lineas FOR EACH ROW EXECUTE FUNCTION public.validar_destino_linea_ecf();
CREATE OR REPLACE FUNCTION public.limpiar_destinos_ecf_desvinculados() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.facturas_ecf_lineas SET transporte_id=NULL WHERE factura_id=OLD.factura_ecf_id AND transporte_id=OLD.transporte_id; RETURN OLD; END $$;
CREATE TRIGGER limpiar_destinos_ecf_desvinculados BEFORE DELETE ON public.transporte_facturas_ecf FOR EACH ROW EXECUTE FUNCTION public.limpiar_destinos_ecf_desvinculados();